1	/**
2	 * pyio.mjs — `print()` and stderr writes with CPython's flushing guarantees.
3	 *
4	 * `process.stdout.write` is asynchronous when stdout is a pipe, so a subsequent
5	 * `process.exit()` can truncate output. Everything here goes through
6	 * `fs.writeSync` instead, which keeps stdout/stderr ordering intact and makes
7	 * the write complete before an exit path runs.
8	 */
9	
10	import { writeSync } from 'node:fs';
11	import { PyBytes, bytesRepr } from './pybytes.mjs';
12	import { pyFloatRepr, pyIntRepr, PyFloat } from './pynumber.mjs';
13	
14	const STDOUT_FD = 1;
15	const STDERR_FD = 2;
16	
17	function writeAllSync(fd, text) {
18	  const buffer = Buffer.from(text, 'utf8');
19	  let offset = 0;
20	  while (offset < buffer.length) {
21	    try {
22	      offset += writeSync(fd, buffer, offset);
23	    } catch (err) {
24	      if (err.code === 'EAGAIN') continue; // non-blocking fd: retry
25	      if (err.code === 'EPIPE') return; // reader went away
26	      throw err;
27	    }
28	  }
29	}
30	
31	export function writeStdout(text) {
32	  writeAllSync(STDOUT_FD, text);
33	}
34	
35	export function writeStderr(text) {
36	  writeAllSync(STDERR_FD, text);
37	}
38	
39	/** `repr()` for the values this program can print. */
40	export function pyRepr(value) {
41	  if (value instanceof PyBytes) return value.repr();
42	  if (value instanceof Uint8Array) return bytesRepr(value);
43	  if (value === null || value === undefined) return 'None';
44	  if (value === true) return 'True';
45	  if (value === false) return 'False';
46	  if (value instanceof PyFloat) return pyFloatRepr(value.value);
47	  if (typeof value === 'bigint') return pyIntRepr(value);
48	  if (typeof value === 'number') {
49	    return Number.isInteger(value) ? pyIntRepr(value) : pyFloatRepr(value);
50	  }
51	  if (Array.isArray(value)) return '[' + value.map(pyRepr).join(', ') + ']';
52	  return String(value);
53	}
54	
55	/**
56	 * `print(*values, sep=' ', end='\n')`.
57	 *
58	 * `print` renders each argument with `str()`, which for `bytes` is its `repr()`
59	 * — that is exactly what `print(result1)` relies on in the Python source.
60	 */
61	export function pyPrint(...values) {
62	  const rendered = values.map((value) => (typeof value === 'string' ? value : pyRepr(value)));
63	  writeStdout(rendered.join(' ') + '\n');
64	}
