/**
 * Campaign: control-and-escapes
 *
 * Exhaustive sweep of the JSON escape table, Python's bytes-repr escape table,
 * and their interaction with argparse / sorting.
 *
 * Usage: node /tmp/dh/control-and-escapes.mjs [shardIndex/shardCount] [groupFilter]
 */
import { runSuite, toBuf } from '/tmp/dh/harness.mjs';

const shardArg = process.argv[2] || '0/1';
const [shardIdx, shardCount] = shardArg.split('/').map(Number);
const groupFilter = process.argv[3] || '';

const cases = [];
let seq = 0;
function add(argv, label) {
  seq += 1;
  cases.push({ argv, label: label || argv.map((a) => toBuf(a).toString('latin1')).join(' | ') });
}

/** Buffer for `--a=<value>` / `--b=<value>` attached forms (avoids leading-dash parsing). */
function attach(opt, value) {
  return Buffer.concat([Buffer.from(opt + '=', 'utf8'), toBuf(value)]);
}
const cp = (n) => String.fromCodePoint(n);

const GROUPS = {};
function group(name, fn) {
  if (groupFilter && !name.includes(groupFilter)) return;
  const before = cases.length;
  fn();
  GROUPS[name] = cases.length - before;
}

// ---------------------------------------------------------------------------
// 1. Every code point 0x01..0xA0 alone (0x00 cannot appear in argv).
// ---------------------------------------------------------------------------
group('singles', () => {
  for (let c = 0x01; c <= 0xa0; c += 1) {
    const v = cp(c);
    // attached form: isolates the escape logic from option parsing
    add([attach('--a', v), attach('--b', 'M')], `single-attached U+${c.toString(16)}`);
    // separate form: exercises argparse's view of the same byte too
    add(['--a', v, '--b', 'M'], `single-sep U+${c.toString(16)}`);
    // as the *second* argument, so sorting has to order it against 'M'
    add([attach('--a', 'M'), attach('--b', v)], `single-b U+${c.toString(16)}`);
  }
});

// ---------------------------------------------------------------------------
// 2. Each code point at start / middle / end / doubled inside a longer string.
// ---------------------------------------------------------------------------
group('positions', () => {
  for (let c = 0x01; c <= 0xa0; c += 1) {
    const v = cp(c);
    const variants = [
      v + 'alpha',            // start
      'alpha' + v + 'omega',  // middle
      'alpha' + v,            // end
      v + v + v,              // only that char, repeated
      'x' + v + v + 'y',      // doubled in the middle
      v + 'a' + v + 'b' + v,  // interleaved
    ];
    for (let i = 0; i < variants.length; i += 1) {
      add([attach('--a', variants[i]), attach('--b', 'mid')], `pos${i} U+${c.toString(16)}`);
    }
  }
});

// ---------------------------------------------------------------------------
// 3. Separate-arg form for the positional variants (argparse sees the raw arg).
// ---------------------------------------------------------------------------
group('positions-sep', () => {
  for (let c = 0x01; c <= 0xa0; c += 1) {
    const v = cp(c);
    add(['--a', 'alpha' + v + 'omega', '--b', 'mid'], `sep-mid U+${c.toString(16)}`);
    add(['--a', 'alpha' + v, '--b', 'mid'], `sep-end U+${c.toString(16)}`);
  }
});

// ---------------------------------------------------------------------------
// 4. Adjacent code point pairs and cross-pairs (combination coverage + sorting).
// ---------------------------------------------------------------------------
group('pairs', () => {
  for (let c = 0x01; c <= 0xa0; c += 1) {
    const nxt = c === 0xa0 ? 0x01 : c + 1;
    add([attach('--a', cp(c) + cp(nxt)), attach('--b', cp(nxt) + cp(c))], `pair ${c.toString(16)}`);
  }
  // every pair drawn from the "interesting" set
  const interesting = [
    0x01, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x1b, 0x1f, 0x20,
    0x22, 0x27, 0x2f, 0x5c, 0x7e, 0x7f, 0x80, 0x85, 0x9f, 0xa0,
  ];
  for (const x of interesting) {
    for (const y of interesting) {
      add([attach('--a', cp(x) + cp(y)), attach('--b', cp(y) + cp(x))], `ipair ${x.toString(16)}/${y.toString(16)}`);
    }
  }
});

// ---------------------------------------------------------------------------
// 5. Backslash / double quote / single quote mixtures — every string of length
//    1..4 over the alphabet {\, ", ', a}. 4 + 16 + 64 + 256 = 340 strings.
// ---------------------------------------------------------------------------
group('quotes', () => {
  const alpha = ['\\', '"', "'", 'a'];
  const strings = [];
  let level = [''];
  for (let len = 1; len <= 4; len += 1) {
    const next = [];
    for (const s of level) for (const ch of alpha) next.push(s + ch);
    strings.push(...next);
    level = next;
  }
  for (const s of strings) {
    add([attach('--a', s), attach('--b', 'Z')], `q ${JSON.stringify(s)}`);
  }
  // both sides from the length<=2 subset, so the quote-selection rule sees the
  // concatenation of two different mixtures
  const short = strings.filter((s) => s.length <= 2);
  for (const s of short) {
    for (const t of short) {
      add([attach('--a', s), attach('--b', t)], `qq ${JSON.stringify(s)}/${JSON.stringify(t)}`);
    }
  }
});

// ---------------------------------------------------------------------------
// 6. Literal backslash sequences that *look* like escapes.
// ---------------------------------------------------------------------------
group('literal-escapes', () => {
  const lits = [
    '\\n', '\\r', '\\t', '\\b', '\\f', '\\v', '\\a', '\\0', '\\\\', '\\"', "\\'",
    '\\x41', '\\x00', '\\x7f', '\\xff', '\\xzz', '\\u0041', '\\u0000', '\\u00e9',
    '\\U0001F600', '\\N{LATIN SMALL LETTER A}', '\\777', '\\1', '\\08',
    '\\\\n', '\\\\\\n', '\\\\\\\\', '\\\\x41', '\\u{1F600}', '\\\\u0041',
    'a\\nb', 'a\\\\nb', '\\n\\n\\n', '\\t\\t', 'C:\\temp\\new', '/\\/\\/\\',
    '\\', '\\\\\\', '\\\\\\\\\\', '%s', '%%', '%d\\n', '${x}', '`x`',
    '\\u0022', '\\u005c', '\\u0027', '"\\n"', "'\\n'", '\\"\\n\\"',
  ];
  for (const s of lits) {
    add([attach('--a', s), attach('--b', 'Z')], `lit ${JSON.stringify(s)}`);
    add(['--a', s, '--b', 'Z'], `lit-sep ${JSON.stringify(s)}`);
  }
  // real escape char next to its literal spelling
  for (const s of lits) {
    add([attach('--a', s + '\n' + s), attach('--b', s + '\t' + s)], `lit-mix ${JSON.stringify(s)}`);
  }
});

// ---------------------------------------------------------------------------
// 7. 0x7f and 0x80..0x9f (and neighbours) as real Unicode code points, plus the
//    wider UTF-8 width boundaries.
// ---------------------------------------------------------------------------
group('c1-and-widths', () => {
  const pts = [];
  for (let c = 0x7b; c <= 0xa5; c += 1) pts.push(c);
  pts.push(0xff, 0x100, 0x7fe, 0x7ff, 0x800, 0x801, 0x2028, 0x2029, 0xd7ff,
          0xe000, 0xfffd, 0xfffe, 0xffff, 0x10000, 0x1f600, 0x10fffe, 0x10ffff);
  for (const c of pts) {
    const v = cp(c);
    add([attach('--a', v), attach('--b', 'M')], `c1 U+${c.toString(16)}`);
    add([attach('--a', 'a' + v + 'z'), attach('--b', 'a' + v)], `c1-embed U+${c.toString(16)}`);
    add([attach('--a', v + '\n' + v), attach('--b', v + '\\n' + v)], `c1-nl U+${c.toString(16)}`);
  }
  // every C1 control adjacent to every JSON-escaped ASCII control
  const asciiCtl = [0x08, 0x09, 0x0a, 0x0c, 0x0d, 0x0b, 0x1f, 0x7f];
  for (let c = 0x80; c <= 0x9f; c += 1) {
    for (const a of asciiCtl) {
      add([attach('--a', cp(a) + cp(c)), attach('--b', cp(c) + cp(a))],
          `c1x ${c.toString(16)}/${a.toString(16)}`);
    }
  }
});

// ---------------------------------------------------------------------------
// 8. Strings made only of escapes.
// ---------------------------------------------------------------------------
group('only-escapes', () => {
  const escOnly = [
    '\b\f\n\r\t', '\t\n\r\f\b', '\\\\\\\\', '""""', "''''", '\\"\\"',
    '',
    '',
    '',
    '',
  ];
  // all 0x01..0x1f in one string, and reversed
  let allCtl = '';
  for (let c = 0x01; c <= 0x1f; c += 1) allCtl += cp(c);
  escOnly.push(allCtl, [...allCtl].reverse().join(''));
  // all 0x01..0xa0 in one string
  let sweep = '';
  for (let c = 0x01; c <= 0xa0; c += 1) sweep += cp(c);
  escOnly.push(sweep, [...sweep].reverse().join(''));
  for (const s of escOnly) {
    add([attach('--a', s), attach('--b', 'Z')], `only-esc len=${s.length}`);
    add([attach('--a', s), attach('--b', s)], `only-esc-both len=${s.length}`);
  }
  // pairwise concatenations
  for (const s of escOnly) {
    for (const t of escOnly) {
      add([attach('--a', s + t), attach('--b', t + s)], `esc-cat ${s.length}/${t.length}`);
    }
  }
});

// ---------------------------------------------------------------------------
// 9. Very long strings (10k+).
// ---------------------------------------------------------------------------
group('long', () => {
  let sweep = '';
  for (let c = 0x01; c <= 0xa0; c += 1) sweep += cp(c);
  const longs = [
    ['ctl10k', ''.repeat(10000)],
    ['nl10k', '\n'.repeat(10000)],
    ['tab12k', '\t'.repeat(12000)],
    ['bs10k', '\\'.repeat(10000)],
    ['dq10k', '"'.repeat(10000)],
    ['sq10k', "'".repeat(10000)],
    ['mix10k', '\\"\''.repeat(4000)],
    ['sweep100x', sweep.repeat(100)],
    ['c1-10k', ''.repeat(10000)],
    ['del10k', ''.repeat(10000)],
    ['bfnrt', '\b\f\n\r\t'.repeat(3000)],
    ['esc-literal', '\\n'.repeat(8000)],
    ['ascii-plus-ctl', ('abcdef' ).repeat(2000)],
    ['nbsp10k', ' '.repeat(10000)],
  ];
  for (const [name, s] of longs) {
    add([attach('--a', s), attach('--b', 'z')], `long ${name} (${s.length})`);
    add([attach('--a', 'z'), attach('--b', s)], `long-b ${name} (${s.length})`);
  }
  // two long strings that differ only at the very end (sorting stress)
  const base = sweep.repeat(80);
  add([attach('--a', base + ''), attach('--b', base + '')], 'long-sort-tail');
  add([attach('--a', base + ''), attach('--b', base + '')], 'long-sort-tail-rev');
  add([attach('--a', base), attach('--b', base)], 'long-equal');
  // 40k
  add([attach('--a', '\\"'.repeat(15000)), attach('--b', 'q')], 'long-45k');
});

// ---------------------------------------------------------------------------
// 10. Escapes interacting with argparse-visible syntax.
// ---------------------------------------------------------------------------
group('argparse-interaction', () => {
  const vals = [
    '', ' ', '=', '==', 'a=b', '--a', '--b', '-a', '-', '--', '-',
    '-', '\n--b', '--a=\n', ' -h', '-h�'.replace('�', ''),
    '\t-h', '\\-h', '--a=--b', '=\\n',
  ];
  for (const v of vals) {
    add([attach('--a', v), attach('--b', 'Z')], `ap ${JSON.stringify(v)}`);
    add([attach('--a', 'Z'), attach('--b', v)], `ap-b ${JSON.stringify(v)}`);
  }
  // separate form for values that cannot be mistaken for an option
  for (const v of vals) {
    if (v.startsWith('-')) continue;
    add(['--a', v, '--b', 'Z'], `ap-sep ${JSON.stringify(v)}`);
  }
});

// ---------------------------------------------------------------------------
// 11. Sorting boundary cases driven purely by control characters.
// ---------------------------------------------------------------------------
group('sort-controls', () => {
  for (let c = 0x01; c <= 0xa0; c += 1) {
    const v = cp(c);
    add([attach('--a', v), attach('--b', cp(0x20))], `sort-vs-space ${c.toString(16)}`);
    add([attach('--a', 'a' + v), attach('--b', 'a')], `sort-prefix ${c.toString(16)}`);
    add([attach('--a', v + 'a'), attach('--b', v)], `sort-prefix2 ${c.toString(16)}`);
  }
});

// ---------------------------------------------------------------------------
// Shard + run.
// ---------------------------------------------------------------------------
const mine = cases.filter((_, i) => i % shardCount === shardIdx);
if (shardIdx === 0) {
  process.stdout.write(`groups: ${JSON.stringify(GROUPS)}\n`);
  process.stdout.write(`total cases: ${cases.length}\n`);
}
const failed = runSuite(`ctl-esc shard ${shardIdx}/${shardCount} (${mine.length})`, mine);
process.exit(failed > 0 ? 1 : 0);

/**
 * Campaign: control-and-escapes
 *
 * Exhaustive sweep of the JSON escape table, Python's bytes-repr escape table,
 * and their interaction with argparse / sorting.
 *
 * Usage: node /tmp/dh/control-and-escapes.mjs [shardIndex/shardCount] [groupFilter]
 */
import { runSuite, toBuf } from '/tmp/dh/harness.mjs';

const shardArg = process.argv[2] || '0/1';
const [shardIdx, shardCount] = shardArg.split('/').map(Number);
const groupFilter = process.argv[3] || '';

const cases = [];
function add(argv, label) {
  cases.push({ argv, label: label || argv.map((a) => toBuf(a).toString('latin1')).join(' | ') });
}

/** Buffer for `--a=<value>` / `--b=<value>` attached forms (avoids leading-dash parsing). */
function attach(opt, value) {
  return Buffer.concat([Buffer.from(opt + '=', 'utf8'), toBuf(value)]);
}
const cp = (n) => String.fromCodePoint(n);
const NL = cp(0x0a);
const TAB = cp(0x09);
const BS = '\'; // a single literal backslash
const DQ = '"';
const SQ = ''';

const GROUPS = {};
function group(name, fn) {
  if (groupFilter && !name.includes(groupFilter)) return;
  const before = cases.length;
  fn();
  GROUPS[name] = cases.length - before;
}

// ---------------------------------------------------------------------------
// 1. Every code point 0x01..0xA0 alone (0x00 cannot appear in argv).
// ---------------------------------------------------------------------------
group('singles', () => {
  for (let c = 0x01; c <= 0xa0; c += 1) {
    const v = cp(c);
    add([attach('--a', v), attach('--b', 'M')], `single-attached U+${c.toString(16)}`);
    add(['--a', v, '--b', 'M'], `single-sep U+${c.toString(16)}`);
    add([attach('--a', 'M'), attach('--b', v)], `single-b U+${c.toString(16)}`);
  }
});

// ---------------------------------------------------------------------------
// 2. Each code point at start / middle / end / doubled inside a longer string.
// ---------------------------------------------------------------------------
group('positions', () => {
  for (let c = 0x01; c <= 0xa0; c += 1) {
    const v = cp(c);
    const variants = [
      v + 'alpha',
      'alpha' + v + 'omega',
      'alpha' + v,
      v + v + v,
      'x' + v + v + 'y',
      v + 'a' + v + 'b' + v,
    ];
    for (let i = 0; i < variants.length; i += 1) {
      add([attach('--a', variants[i]), attach('--b', 'mid')], `pos${i} U+${c.toString(16)}`);
    }
  }
});

// ---------------------------------------------------------------------------
// 3. Separate-arg form (argparse sees the raw arg, not an `=` payload).
// ---------------------------------------------------------------------------
group('positions-sep', () => {
  for (let c = 0x01; c <= 0xa0; c += 1) {
    const v = cp(c);
    add(['--a', 'alpha' + v + 'omega', '--b', 'mid'], `sep-mid U+${c.toString(16)}`);
    add(['--a', 'alpha' + v, '--b', 'mid'], `sep-end U+${c.toString(16)}`);
  }
});

// ---------------------------------------------------------------------------
// 4. Adjacent code point pairs and cross-pairs (combination + sorting).
// ---------------------------------------------------------------------------
group('pairs', () => {
  for (let c = 0x01; c <= 0xa0; c += 1) {
    const nxt = c === 0xa0 ? 0x01 : c + 1;
    add([attach('--a', cp(c) + cp(nxt)), attach('--b', cp(nxt) + cp(c))], `pair ${c.toString(16)}`);
  }
  const interesting = [
    0x01, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x1b, 0x1f, 0x20,
    0x22, 0x27, 0x2f, 0x5c, 0x7e, 0x7f, 0x80, 0x85, 0x9f, 0xa0,
  ];
  for (const x of interesting) {
    for (const y of interesting) {
      add([attach('--a', cp(x) + cp(y)), attach('--b', cp(y) + cp(x))],
          `ipair ${x.toString(16)}/${y.toString(16)}`);
    }
  }
  // triples over a smaller interesting set: 8^3 = 512
  const tri = [0x08, 0x09, 0x0a, 0x0c, 0x0d, 0x22, 0x27, 0x5c];
  for (const x of tri) {
    for (const y of tri) {
      for (const z of tri) {
        add([attach('--a', cp(x) + cp(y) + cp(z)), attach('--b', 'T')],
            `tri ${x.toString(16)}${y.toString(16)}${z.toString(16)}`);
      }
    }
  }
});

// ---------------------------------------------------------------------------
// 5. Backslash / double quote / single quote mixtures — every string of length
//    1..4 over the alphabet {\, ", ', a}. 4 + 16 + 64 + 256 = 340 strings.
// ---------------------------------------------------------------------------
group('quotes', () => {
  const alpha = [BS, DQ, SQ, 'a'];
  const strings = [];
  let level = [''];
  for (let len = 1; len <= 4; len += 1) {
    const next = [];
    for (const s of level) for (const ch of alpha) next.push(s + ch);
    strings.push(...next);
    level = next;
  }
  for (const s of strings) {
    add([attach('--a', s), attach('--b', 'Z')], `q ${JSON.stringify(s)}`);
  }
  const short = strings.filter((s) => s.length <= 2);
  for (const s of short) {
    for (const t of short) {
      add([attach('--a', s), attach('--b', t)], `qq ${JSON.stringify(s)}/${JSON.stringify(t)}`);
    }
  }
  // quotes adjacent to controls
  for (const s of strings.filter((x) => x.length === 2)) {
    add([attach('--a', s + NL + s), attach('--b', TAB + s)], `q-ctl ${JSON.stringify(s)}`);
  }
});

// ---------------------------------------------------------------------------
// 6. Literal backslash sequences that *look* like escapes.
// ---------------------------------------------------------------------------
const LITS = [
  BS + 'n', BS + 'r', BS + 't', BS + 'b', BS + 'f', BS + 'v', BS + 'a', BS + '0',
  BS + BS, BS + DQ, BS + SQ,
  BS + 'x41', BS + 'x00', BS + 'x7f', BS + 'xff', BS + 'xzz',
  BS + 'u0041', BS + 'u0000', BS + 'u00e9', BS + 'U0001F600',
  BS + 'N{LATIN SMALL LETTER A}', BS + '777', BS + '1', BS + '08',
  BS + BS + 'n', BS + BS + BS + 'n', BS + BS + BS + BS, BS + BS + 'x41',
  BS + 'u{1F600}', BS + BS + 'u0041',
  'a' + BS + 'nb', 'a' + BS + BS + 'nb', (BS + 'n').repeat(3), (BS + 't').repeat(2),
  'C:' + BS + 'temp' + BS + 'new', ('/' + BS).repeat(3),
  BS, BS.repeat(3), BS.repeat(5),
  '%s', '%%', '%d' + BS + 'n', '${x}', '`x`',
  BS + 'u0022', BS + 'u005c', BS + 'u0027',
  DQ + BS + 'n' + DQ, SQ + BS + 'n' + SQ, BS + DQ + BS + 'n' + BS + DQ,
  BS + 'x' + cp(0x0a), BS + cp(0x0a), BS + cp(0x09), BS + cp(0x7f), BS + cp(0x80),
];
group('literal-escapes', () => {
  for (const s of LITS) {
    add([attach('--a', s), attach('--b', 'Z')], `lit ${JSON.stringify(s)}`);
    add(['--a', s, '--b', 'Z'], `lit-sep ${JSON.stringify(s)}`);
  }
  for (const s of LITS) {
    add([attach('--a', s + NL + s), attach('--b', s + TAB + s)], `lit-mix ${JSON.stringify(s)}`);
  }
  // literal escape spellings against each other (sorting)
  for (let i = 0; i < LITS.length; i += 1) {
    add([attach('--a', LITS[i]), attach('--b', LITS[(i + 1) % LITS.length])], `lit-sort ${i}`);
  }
});

// ---------------------------------------------------------------------------
// 7. 0x7f and 0x80..0x9f (and neighbours) as real Unicode code points, plus the
//    UTF-8 width boundaries.
// ---------------------------------------------------------------------------
group('c1-and-widths', () => {
  const pts = [];
  for (let c = 0x7b; c <= 0xa5; c += 1) pts.push(c);
  pts.push(0xff, 0x100, 0x7fe, 0x7ff, 0x800, 0x801, 0x2028, 0x2029, 0xd7ff,
           0xe000, 0xfffd, 0xfffe, 0xffff, 0x10000, 0x1f600, 0x10fffe, 0x10ffff);
  for (const c of pts) {
    const v = cp(c);
    add([attach('--a', v), attach('--b', 'M')], `c1 U+${c.toString(16)}`);
    add([attach('--a', 'a' + v + 'z'), attach('--b', 'a' + v)], `c1-embed U+${c.toString(16)}`);
    add([attach('--a', v + NL + v), attach('--b', v + BS + 'n' + v)], `c1-nl U+${c.toString(16)}`);
  }
  const asciiCtl = [0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1f, 0x7f];
  for (let c = 0x80; c <= 0xa0; c += 1) {
    for (const a of asciiCtl) {
      add([attach('--a', cp(a) + cp(c)), attach('--b', cp(c) + cp(a))],
          `c1x ${c.toString(16)}/${a.toString(16)}`);
    }
  }
});

// ---------------------------------------------------------------------------
// 8. Strings made only of escapes.
// ---------------------------------------------------------------------------
group('only-escapes', () => {
  let allCtl = '';
  for (let c = 0x01; c <= 0x1f; c += 1) allCtl += cp(c);
  let sweep = '';
  for (let c = 0x01; c <= 0xa0; c += 1) sweep += cp(c);

  const escOnly = [
    cp(8) + cp(12) + cp(10) + cp(13) + cp(9),
    cp(9) + cp(10) + cp(13) + cp(12) + cp(8),
    BS.repeat(4), DQ.repeat(4), SQ.repeat(4), (BS + DQ).repeat(2),
    cp(0x0b).repeat(4),
    cp(0x1f) + cp(0x1e) + cp(0x1d) + cp(0x1c),
    cp(0x7f).repeat(4),
    cp(0x80) + cp(0x9f) + cp(0xa0),
    cp(0x01) + cp(0x02) + cp(0x03),
    allCtl,
    [...allCtl].reverse().join(''),
    sweep,
    [...sweep].reverse().join(''),
  ];
  for (const s of escOnly) {
    add([attach('--a', s), attach('--b', 'Z')], `only-esc len=${s.length}`);
    add([attach('--a', s), attach('--b', s)], `only-esc-both len=${s.length}`);
  }
  for (const s of escOnly) {
    for (const t of escOnly) {
      add([attach('--a', s + t), attach('--b', t + s)], `esc-cat ${s.length}/${t.length}`);
    }
  }
});

// ---------------------------------------------------------------------------
// 9. Very long strings (10k+).
// ---------------------------------------------------------------------------
group('long', () => {
  let sweep = '';
  for (let c = 0x01; c <= 0xa0; c += 1) sweep += cp(c);
  const longs = [
    ['ctl10k', cp(0x01).repeat(10000)],
    ['nl10k', NL.repeat(10000)],
    ['tab12k', TAB.repeat(12000)],
    ['bs10k', BS.repeat(10000)],
    ['dq10k', DQ.repeat(10000)],
    ['sq10k', SQ.repeat(10000)],
    ['mix10k', (BS + DQ + SQ).repeat(4000)],
    ['sweep100x', sweep.repeat(100)],
    ['c1-10k', cp(0x9f).repeat(10000)],
    ['del10k', cp(0x7f).repeat(10000)],
    ['bfnrt', (cp(8) + cp(12) + cp(10) + cp(13) + cp(9)).repeat(3000)],
    ['esc-literal', (BS + 'n').repeat(8000)],
    ['ascii-plus-ctl', ('abc' + cp(0x1b) + cp(0x0b) + cp(0x7f)).repeat(2000)],
    ['nbsp10k', cp(0xa0).repeat(10000)],
    ['vt-ff', (cp(0x0b) + cp(0x0c)).repeat(6000)],
  ];
  for (const [name, s] of longs) {
    add([attach('--a', s), attach('--b', 'z')], `long ${name} (${s.length})`);
    add([attach('--a', 'z'), attach('--b', s)], `long-b ${name} (${s.length})`);
  }
  const base = sweep.repeat(80);
  add([attach('--a', base + cp(0x01)), attach('--b', base + cp(0x02))], 'long-sort-tail');
  add([attach('--a', base + cp(0x02)), attach('--b', base + cp(0x01))], 'long-sort-tail-rev');
  add([attach('--a', base), attach('--b', base)], 'long-equal');
  add([attach('--a', (BS + DQ).repeat(15000)), attach('--b', 'q')], 'long-45k');
  add([attach('--a', sweep.repeat(60)), attach('--b', sweep.repeat(60) + NL)], 'long-both');
});

// ---------------------------------------------------------------------------
// 10. Escapes interacting with argparse-visible syntax.
// ---------------------------------------------------------------------------
group('argparse-interaction', () => {
  const vals = [
    '', ' ', '=', '==', 'a=b', '--a', '--b', '-a', '-', '--',
    NL, NL + '--b', '--a=' + NL, ' -h', TAB + '-h', BS + '-h', '--a=--b',
    '=' + BS + 'n', '-' + cp(0x01), '-' + NL, '--' + TAB, '-h' + NL, DQ + '-h' + DQ,
  ];
  for (const v of vals) {
    add([attach('--a', v), attach('--b', 'Z')], `ap ${JSON.stringify(v)}`);
    add([attach('--a', 'Z'), attach('--b', v)], `ap-b ${JSON.stringify(v)}`);
  }
  for (const v of vals) {
    if (v.startsWith('-')) continue;
    add(['--a', v, '--b', 'Z'], `ap-sep ${JSON.stringify(v)}`);
  }
});

// ---------------------------------------------------------------------------
// 11. Sorting boundary cases driven purely by control characters.
// ---------------------------------------------------------------------------
group('sort-controls', () => {
  for (let c = 0x01; c <= 0xa0; c += 1) {
    const v = cp(c);
    add([attach('--a', v), attach('--b', cp(0x20))], `sort-vs-space ${c.toString(16)}`);
    add([attach('--a', 'a' + v), attach('--b', 'a')], `sort-prefix ${c.toString(16)}`);
    add([attach('--a', v + 'a'), attach('--b', v)], `sort-prefix2 ${c.toString(16)}`);
  }
});

// ---------------------------------------------------------------------------
// Shard + run.
// ---------------------------------------------------------------------------
const mine = cases.filter((_, i) => i % shardCount === shardIdx);
if (process.env.CE_LIST === '1') {
  process.stdout.write(`groups: ${JSON.stringify(GROUPS, null, 1)}\n`);
  process.stdout.write(`total cases: ${cases.length}\n`);
  process.exit(0);
}
const failed = runSuite(`ctl-esc ${shardIdx}/${shardCount} (${mine.length})`, mine);
process.exit(failed > 0 ? 1 : 0);

