input.content:
/**
 * Campaign: control-and-escapes — round 2 (high volume).
 *
 * Usage: node /tmp/dh/ce2.mjs [shardIndex/shardCount]
 *        CE_LIST=1 node /tmp/dh/ce2.mjs   # just count
 */
import { runSuite, toBuf } from '/tmp/dh/harness.mjs';

const [shardIdx, shardCount] = (process.argv[2] || '0/1').split('/').map(Number);
const only = process.argv[3] || '';

const cases = [];
const add = (argv, label) => cases.push({ argv, label });

const cp = (n) => String.fromCodePoint(n);
const B = (...parts) => Buffer.concat(parts.map(toBuf));
/** `--a=<parts...>` with exact bytes (parts may be strings or Buffers). */
const at = (opt, ...parts) => B(opt + '=', ...parts);

const GROUPS = {};
function group(name, fn) {
  if (only && !name.includes(only)) return;
  const before = cases.length;
  fn();
  GROUPS[name] = cases.length - before;
}

// ---------------------------------------------------------------------------
// A. Exhaustive cross product: every code point 0x01..0xA0 in --a against every
//    code point 0x01..0xA0 in --b. 160 * 160 = 25600 cases. This is the full
//    "in combination" pass: it exercises both escape tables and sorted().
// ---------------------------------------------------------------------------
group('cross-160x160', () => {
  for (let x = 0x01; x <= 0xa0; x += 1) {
    for (let y = 0x01; y <= 0xa0; y += 1) {
      add([at('--a', cp(x)), at('--b', cp(y))], `cross ${x.toString(16)}/${y.toString(16)}`);
    }
  }
});

// ---------------------------------------------------------------------------
// B. Exhaustive length-3 strings over the full escape alphabet.
//    12^3 = 1728, each against a constant --b.
// ---------------------------------------------------------------------------
group('triples-escape-alphabet', () => {
  const A = [0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1f, 0x22, 0x27, 0x2f, 0x5c, 0x7f];
  for (const x of A) {
    for (const y of A) {
      for (const z of A) {
        add([at('--a', cp(x) + cp(y) + cp(z)), at('--b', 'k')],
            `t3 ${x.toString(16)}.${y.toString(16)}.${z.toString(16)}`);
      }
    }
  }
  // and length-2 over the same alphabet in both args: 144 * ... keep to pairs
  for (const x of A) {
    for (const y of A) {
      add([at('--a', cp(x) + cp(y)), at('--b', cp(y) + cp(x))],
          `t2both ${x.toString(16)}.${y.toString(16)}`);
    }
  }
});

// ---------------------------------------------------------------------------
// C. Escape expansion vs UnicodeEncodeError position arithmetic.
//    A JSON escape makes the text longer than the input, so the reported
//    surrogate position must be measured against the *encoded* text.
// ---------------------------------------------------------------------------
group('escape-expansion-error-pos', () => {
  const prefixCps = [0x01, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1f, 0x22, 0x5c, 0x7f,
                     0x80, 0xa0, 0x41, 0x2f];
  const badBytes = [[0x80], [0xff], [0xc0], [0xf5], [0xed, 0xa0, 0x80], [0xc2], [0xe0, 0x80]];
  for (const pc of prefixCps) {
    for (let n = 0; n <= 3; n += 1) {
      for (const bad of badBytes) {
        const pre = cp(pc).repeat(n);
        add([at('--a', pre, Buffer.from(bad)), at('--b', 'x')],
            `expand ${pc.toString(16)}x${n} + ${bad.map((b) => b.toString(16)).join('')}`);
      }
    }
  }
  // bad byte in --b instead, and in both
  for (const pc of prefixCps) {
    add([at('--a', 'x'), at('--b', cp(pc).repeat(2), Buffer.from([0x80]))], `expand-b ${pc.toString(16)}`);
    add([at('--a', cp(pc), Buffer.from([0x81])), at('--b', cp(pc), Buffer.from([0x82]))],
        `expand-both ${pc.toString(16)}`);
  }
  // runs of invalid bytes separated by escaped controls (error *range* reporting)
  const seps = [0x0a, 0x09, 0x0b, 0x22, 0x5c, 0x41, 0x7f];
  for (const s of seps) {
    for (let run = 1; run <= 4; run += 1) {
      const bad = Buffer.alloc(run, 0x80);
      add([at('--a', cp(s), bad, cp(s)), at('--b', 'y')], `run ${s.toString(16)}x${run}`);
      add([at('--a', bad, cp(s), bad), at('--b', 'y')], `run2 ${s.toString(16)}x${run}`);
    }
  }
});

// ---------------------------------------------------------------------------
// D. Raw byte 0x01..0x7F delivered as bytes (identical to code points) plus the
//    0x80..0xA0 range delivered BOTH as raw bytes (invalid UTF-8) and as real
//    code points, so the two paths can be told apart.
// ---------------------------------------------------------------------------
group('raw-bytes-vs-codepoints', () => {
  for (let b = 0x01; b <= 0xa0; b += 1) {
    add([at('--a', Buffer.from([b])), at('--b', 'M')], `raw ${b.toString(16)}`);
    add([at('--a', 'a', Buffer.from([b]), 'z'), at('--b', 'M')], `raw-mid ${b.toString(16)}`);
    add([at('--a', cp(b)), at('--b', Buffer.from([b]))], `raw-vs-cp ${b.toString(16)}`);
  }
  // valid 2-byte UTF-8 for every C1 control, spelled explicitly
  for (let c = 0x80; c <= 0xa0; c += 1) {
    const lead = 0xc0 | (c >> 6);
    const cont = 0x80 | (c & 0x3f);
    add([at('--a', Buffer.from([lead, cont])), at('--b', cp(c))], `c1-explicit ${c.toString(16)}`);
  }
});

// ---------------------------------------------------------------------------
// E. Longer strings: escape-heavy payloads from 10k to 200k characters.
// ---------------------------------------------------------------------------
group('very-long', () => {
  const BS = cp(0x5c), DQ = cp(0x22), SQ = cp(0x27);
  let sweep = '';
  for (let c = 0x01; c <= 0xa0; c += 1) sweep += cp(c);
  const items = [
    ['sweep-200x', sweep.repeat(200)],          // 32000 cp, ~ heavy expansion
    ['sweep-600x', sweep.repeat(600)],          // 96000 cp
    ['nl-50k', cp(0x0a).repeat(50000)],
    ['bs-50k', BS.repeat(50000)],
    ['dq-50k', DQ.repeat(50000)],
    ['sq-50k', SQ.repeat(50000)],
    ['ctl1-100k', cp(0x01).repeat(100000)],
    ['vt-100k', cp(0x0b).repeat(100000)],
    ['del-100k', cp(0x7f).repeat(100000)],
    ['c1-50k', cp(0x9f).repeat(50000)],
    ['nbsp-50k', cp(0xa0).repeat(50000)],
    ['mixed-60k', (BS + DQ + cp(0x0a) + cp(0x1f) + cp(0x7f) + cp(0x9f)).repeat(10000)],
    ['literal-n-50k', (BS + 'n').repeat(25000)],
  ];
  for (const [name, s] of items) {
    add([at('--a', s), at('--b', 'z')], `vlong ${name} (${s.length})`);
    add([at('--a', s), at('--b', s)], `vlong-both ${name} (${s.length})`);
  }
  // long string terminated by an invalid byte: error position must be huge
  add([at('--a', cp(0x0a).repeat(5000), Buffer.from([0x80])), at('--b', 'z')], 'vlong-bad-tail-nl');
  add([at('--a', cp(0x01).repeat(5000), Buffer.from([0x80])), at('--b', 'z')], 'vlong-bad-tail-ctl');
  add([at('--a', cp(0x9f).repeat(5000), Buffer.from([0xff])), at('--b', 'z')], 'vlong-bad-tail-c1');
  add([at('--a', cp(0x5c).repeat(5000), Buffer.from([0xfe])), at('--b', 'z')], 'vlong-bad-tail-bs');
});

// ---------------------------------------------------------------------------
// F. Quote-selection stress: every combination of "how many ' and how many \"".
// ---------------------------------------------------------------------------
group('quote-selection', () => {
  const SQ = cp(0x27), DQ = cp(0x22), BS = cp(0x5c);
  for (let ns = 0; ns <= 5; ns += 1) {
    for (let nd = 0; nd <= 5; nd += 1) {
      for (let nb = 0; nb <= 2; nb += 1) {
        const v = SQ.repeat(ns) + DQ.repeat(nd) + BS.repeat(nb);
        add([at('--a', v), at('--b', 'Q')], `qs ${ns}/${nd}/${nb}`);
        add([at('--a', v), at('--b', BS.repeat(nb) + DQ.repeat(nd) + SQ.repeat(ns))],
            `qs-both ${ns}/${nd}/${nb}`);
      }
    }
  }
  // interleaved rather than grouped
  for (let n = 1; n <= 6; n += 1) {
    add([at('--a', (SQ + DQ).repeat(n)), at('--b', (DQ + SQ).repeat(n))], `qs-inter ${n}`);
    add([at('--a', (SQ + BS).repeat(n)), at('--b', (BS + SQ).repeat(n))], `qs-interb ${n}`);
    add([at('--a', (SQ + BS + DQ).repeat(n)), at('--b', 'Q')], `qs-inter3 ${n}`);
  }
});

// ---------------------------------------------------------------------------
// G. Surrogate code points spelled as UTF-8 (invalid) mixed with escapes, plus
//    astral characters mixed with controls (sorting + 4-byte encoding).
// ---------------------------------------------------------------------------
group('astral-and-surrogates', () => {
  const astral = [0x10000, 0x1f600, 0x2f800, 0x10ffff];
  const ctl = [0x01, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1f, 0x22, 0x5c, 0x7f, 0x80, 0xa0];
  for (const a of astral) {
    for (const c of ctl) {
      add([at('--a', cp(a) + cp(c)), at('--b', cp(c) + cp(a))],
          `astral ${a.toString(16)}/${c.toString(16)}`);
    }
  }
  // CESU-style / surrogate-encoded bytes next to escapes
  const surBytes = [
    [0xed, 0xa0, 0x80], // U+D800
    [0xed, 0xbf, 0xbf], // U+DFFF
    [0xed, 0xb2, 0x80], // U+DC80
  ];
  for (const sb of surBytes) {
    for (const c of ctl) {
      add([at('--a', cp(c), Buffer.from(sb)), at('--b', 'z')],
          `sur ${sb.map((x) => x.toString(16)).join('')}/${c.toString(16)}`);
    }
  }
});

const mine = cases.filter((_, i) => i % shardCount === shardIdx);
if (process.env.CE_LIST === '1') {
  process.stdout.write(`groups: ${JSON.stringify(GROUPS, null, 1)}\ntotal: ${cases.length}\n`);
  process.exit(0);
}
const failed = runSuite(`ce2 ${shardIdx}/${shardCount} (${mine.length})`, mine);
process.exit(failed > 0 ? 1 : 0);

