/**
 * Very long argv values (100k .. 900k characters).
 *
 * /tmp/dh/harness.mjs renders argv as `\xNN` escapes inside one `bash -c`
 * string, which the kernel caps at MAX_ARG_STRLEN (128 KiB) — about 32000 argv
 * bytes. To go beyond that this runner skips bash and spawns each program
 * directly, so a value may be up to 128 KiB of *bytes* per argument. Only valid
 * UTF-8 can be delivered this way (Node stringifies spawn arguments), which is
 * fine: invalid-UTF-8 handling is covered through the harness.
 *
 * Comparison is the same as checkCase: stdout and exit code byte-exact, stderr
 * with the PyInstaller pid masked.
 */
import { spawnSync } from 'node:child_process';

const PY = '/workspace/dataset/test7_executable';
const JS = '/output/test7.mjs';
const MAX = 1 << 26;

function compare(label, argv) {
  const py = spawnSync(PY, argv, { maxBuffer: MAX });
  const js = spawnSync(process.execPath, [JS, ...argv], { maxBuffer: MAX });
  const problems = [];
  if (py.error) problems.push(`py spawn error: ${py.error.message}`);
  if (js.error) problems.push(`js spawn error: ${js.error.message}`);
  if (!py.error && !js.error) {
    if (!py.stdout.equals(js.stdout)) {
      problems.push(
        `stdout differs (py ${py.stdout.length} B, js ${js.stdout.length} B)` +
          firstDiff(py.stdout, js.stdout),
      );
    }
    if (py.status !== js.status) problems.push(`exit code py=${py.status} js=${js.status}`);
    const mask = (b) => b.toString('utf8').replace(/\[PYI-\d+:ERROR\]/g, '[PYI:ERROR]');
    if (mask(py.stderr) !== mask(js.stderr)) {
      problems.push(`stderr differs\n  py: ${mask(py.stderr).slice(0, 400)}\n  js: ${mask(js.stderr).slice(0, 400)}`);
    }
  }
  if (problems.length) {
    process.stdout.write(`FAIL ${label}\n`);
    for (const p of problems) process.stdout.write('  ' + p.replace(/\n/g, '\n  ') + '\n');
  }
  return problems.length ? 1 : 0;
}

function firstDiff(a, b) {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i += 1) {
    if (a[i] !== b[i]) {
      return `\n  first diff at byte ${i}: py=${a.slice(i, i + 24).toString('latin1')} js=${b
        .slice(i, i + 24)
        .toString('latin1')}`;
    }
  }
  return '\n  (one is a prefix of the other)';
}

const cp = (n) => String.fromCodePoint(n);
const BS = cp(0x5c), DQ = cp(0x22), SQ = cp(0x27);
let sweep = '';
for (let c = 0x01; c <= 0xa0; c += 1) sweep += cp(c);       // 160 cp / 193 bytes

// Per-argument byte budget is 128 KiB, so keep 1-byte payloads under ~130000
// and 2-byte payloads under ~65000.
const cases = [
  ['nl-100k', cp(0x0a).repeat(100000), 'z'],
  ['ctl1-120k', cp(0x01).repeat(120000), 'z'],
  ['vt-120k', cp(0x0b).repeat(120000), 'z'],
  ['tab-120k', cp(0x09).repeat(120000), 'z'],
  ['bs-120k', BS.repeat(120000), 'z'],
  ['dq-120k', DQ.repeat(120000), 'z'],
  ['sq-120k', SQ.repeat(120000), 'z'],
  ['del-120k', cp(0x7f).repeat(120000), 'z'],
  ['c1-60k', cp(0x9f).repeat(60000), 'z'],
  ['nbsp-60k', cp(0xa0).repeat(60000), 'z'],
  ['sweep-600x', sweep.repeat(600), 'z'],                    // 96000 cp
  ['literal-n-60k', (BS + 'n').repeat(60000), 'z'],
  ['mixed-100k', (BS + DQ + cp(0x0a) + cp(0x1f) + cp(0x7f)).repeat(20000), 'z'],
  ['both-nl-60k', cp(0x0a).repeat(60000), cp(0x09).repeat(60000)],
  ['both-bs-60k', BS.repeat(60000), DQ.repeat(60000)],
  ['both-sweep', sweep.repeat(300), sweep.repeat(300) + cp(0x01)],
  ['both-equal', sweep.repeat(300), sweep.repeat(300)],
  ['sort-tail', sweep.repeat(300) + cp(0x02), sweep.repeat(300) + cp(0x01)],
  ['escape-heavy-astral', (cp(0x1f600) + cp(0x0a)).repeat(20000), 'z'],
];

let failed = 0;
let n = 0;
for (const [label, a, b] of cases) {
  n += 1;
  failed += compare(`${label} (a=${a.length} cp / ${Buffer.byteLength(a)} B)`, [
    '--a=' + a,
    '--b=' + b,
  ]);
}
process.stdout.write(`[ce-long] ${n - failed}/${n} passed\n`);
process.exit(failed ? 1 : 0);
